import sys

def kmp_search(text, pattern):
    m = len(pattern)
    n = len(text)
    if m == 0:
        return []

    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    result = []
    i = 0
    j = 0
    while i < n:
        if pattern[j] == text[i]:
            i += 1
            j += 1
        if j == m:
            result.append(i - j + 1)
            j = lps[j - 1]
        elif i < n and pattern[j] != text[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return result

def main():
    lines = sys.stdin.read().splitlines()
    s_line = lines[0].strip()
    pat_line = lines[1].strip()

    if s_line.startswith('S = ') and '"' in s_line:
        s_line = s_line.split('"')[1]
    if pat_line.startswith('pat = ') and '"' in pat_line:
        pat_line = pat_line.split('"')[1]

    indices = kmp_search(s_line, pat_line)

    if indices:
        print(' '.join(map(str, indices)))
    else:
        print('-1')

if __name__ == "__main__":
    main()
